'use strict';

const fs = require('node:fs');

// Errors caused by bad user input or bad data. The CLI prints the message
// without a stack trace.
class TodoError extends Error {}

function isValidTodo(todo) {
  return (
    todo !== null &&
    typeof todo === 'object' &&
    Number.isSafeInteger(todo.id) &&
    todo.id > 0 &&
    typeof todo.text === 'string' &&
    typeof todo.completed === 'boolean'
  );
}

// Returns the todos stored in `file`. A missing or empty file counts as an
// empty list. Anything unparseable is rejected so it never gets overwritten.
function loadTodos(file) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw new TodoError(`Could not read ${file}: ${err.message}`);
  }
  if (raw.trim() === '') return [];

  let todos;
  try {
    todos = JSON.parse(raw);
  } catch {
    throw new TodoError(`${file} is not valid JSON. Fix or remove it and try again.`);
  }
  if (!Array.isArray(todos) || !todos.every(isValidTodo)) {
    throw new TodoError(`${file} does not contain a valid list of todos. Fix or remove it and try again.`);
  }
  return todos;
}

// Writes to a temp file and renames it into place, so a crash mid-write
// can't leave a truncated todos.json behind.
function saveTodos(file, todos) {
  const tmp = `${file}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tmp, JSON.stringify(todos, null, 2) + '\n');
    fs.renameSync(tmp, file);
  } catch (err) {
    fs.rmSync(tmp, { force: true });
    throw err;
  }
}

function addTodo(todos, text, now = new Date()) {
  const trimmed = text.trim();
  if (trimmed === '') throw new TodoError('Todo text cannot be empty.');

  const id = todos.reduce((max, todo) => Math.max(max, todo.id), 0) + 1;
  const todo = { id, text: trimmed, completed: false, createdAt: now.toISOString() };
  todos.push(todo);
  return todo;
}

function findTodo(todos, id) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) throw new TodoError(`No todo found with ID ${id}.`);
  return todo;
}

function deleteTodo(todos, id) {
  const index = todos.findIndex((t) => t.id === id);
  if (index === -1) throw new TodoError(`No todo found with ID ${id}.`);
  return todos.splice(index, 1)[0];
}

function parseId(arg) {
  const id = Number(arg);
  if (!/^\d+$/.test(arg) || !Number.isSafeInteger(id) || id < 1) {
    throw new TodoError(`Invalid ID "${arg}". IDs are positive whole numbers.`);
  }
  return id;
}

// One line per todo, e.g. " 9. [ ] Buy milk" / "10. [x] Pay rent".
function formatTodos(todos) {
  const width = Math.max(...todos.map((t) => String(t.id).length));
  return todos
    .map((t) => `${String(t.id).padStart(width)}. [${t.completed ? 'x' : ' '}] ${t.text}`)
    .join('\n');
}

module.exports = {
  TodoError,
  loadTodos,
  saveTodos,
  addTodo,
  findTodo,
  deleteTodo,
  parseId,
  formatTodos,
};

