'use strict';

const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const {
  TodoError,
  loadTodos,
  saveTodos,
  addTodo,
  findTodo,
  deleteTodo,
  parseId,
  formatTodos,
} = require('../lib/todos');

function todo(id, text, completed = false) {
  return { id, text, completed, createdAt: '2026-01-01T00:00:00.000Z' };
}

describe('loadTodos / saveTodos', () => {
  let dir;
  let file;

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-unit-'));
    file = path.join(dir, 'todos.json');
  });

  afterEach(() => {
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('returns an empty list when the file does not exist', () => {
    assert.deepEqual(loadTodos(file), []);
  });

  it('returns an empty list when the file is empty or whitespace', () => {
    fs.writeFileSync(file, '');
    assert.deepEqual(loadTodos(file), []);
    fs.writeFileSync(file, '  \n');
    assert.deepEqual(loadTodos(file), []);
  });

  it('round-trips todos through the file', () => {
    const todos = [todo(1, 'a'), todo(2, 'b', true)];
    saveTodos(file, todos);
    assert.deepEqual(loadTodos(file), todos);
  });

  it('writes pretty-printed JSON with a trailing newline', () => {
    saveTodos(file, [todo(1, 'a')]);
    const raw = fs.readFileSync(file, 'utf8');
    assert.equal(raw, JSON.stringify([todo(1, 'a')], null, 2) + '\n');
  });

  it('leaves no temp files behind after saving', () => {
    saveTodos(file, [todo(1, 'a')]);
    assert.deepEqual(fs.readdirSync(dir), ['todos.json']);
  });

  it('overwrites the previous contents on save', () => {
    saveTodos(file, [todo(1, 'a'), todo(2, 'b')]);
    saveTodos(file, [todo(2, 'b')]);
    assert.deepEqual(loadTodos(file), [todo(2, 'b')]);
  });

  it('rejects invalid JSON', () => {
    fs.writeFileSync(file, '{ not json');
    assert.throws(() => loadTodos(file), { name: 'Error', message: /not valid JSON/ });
    assert.throws(() => loadTodos(file), TodoError);
  });

  it('rejects JSON that is not an array', () => {
    fs.writeFileSync(file, '{"id": 1}');
    assert.throws(() => loadTodos(file), /not contain a valid list/);
  });

  it('rejects arrays containing malformed todos', () => {
    const bad = [
      [null],
      ['a string'],
      [{ text: 'no id', completed: false }],
      [{ id: '1', text: 'string id', completed: false }],
      [{ id: 0, text: 'zero id', completed: false }],
      [{ id: 1.5, text: 'fractional id', completed: false }],
      [{ id: 1, completed: false }],
      [{ id: 1, text: 'string completed', completed: 'no' }],
    ];
    for (const todos of bad) {
      fs.writeFileSync(file, JSON.stringify(todos));
