    const todos = [];
    assert.throws(() => addTodo(todos, ''), TodoError);
    assert.throws(() => addTodo(todos, '   \t\n'), /cannot be empty/);
    assert.deepEqual(todos, []);
  });
});

describe('findTodo', () => {
  it('returns the matching todo', () => {
    const todos = [todo(1, 'a'), todo(2, 'b')];
    assert.equal(findTodo(todos, 2), todos[1]);
  });

  it('throws when the id does not exist', () => {
    assert.throws(() => findTodo([todo(1, 'a')], 5), { message: 'No todo found with ID 5.' });
    assert.throws(() => findTodo([], 1), TodoError);
  });
});

describe('deleteTodo', () => {
  it('removes and returns the matching todo', () => {
    const todos = [todo(1, 'a'), todo(2, 'b'), todo(3, 'c')];
    const removed = deleteTodo(todos, 2);
    assert.deepEqual(removed, todo(2, 'b'));
    assert.deepEqual(todos, [todo(1, 'a'), todo(3, 'c')]);
  });

  it('throws and leaves the list unchanged when the id does not exist', () => {
    const todos = [todo(1, 'a')];
    assert.throws(() => deleteTodo(todos, 9), /No todo found with ID 9/);
