  });
});

describe('parseId', () => {
  it('parses positive integers', () => {
    assert.equal(parseId('1'), 1);
    assert.equal(parseId('42'), 42);
    assert.equal(parseId('007'), 7);
  });

  for (const input of ['0', '-1', '1.5', '1e3', 'abc', '', ' 1', '1 ', '0x10', '3abc', '99999999999999999999']) {
    it(`rejects ${JSON.stringify(input)}`, () => {
      assert.throws(() => parseId(input), { message: `Invalid ID "${input}". IDs are positive whole numbers.` });
    });
  }
});

describe('formatTodos', () => {
  it('shows id, status indicator and text for each todo', () => {
    const output = formatTodos([todo(1, 'Buy groceries'), todo(2, 'Walk dog', true)]);
    assert.equal(output, '1. [ ] Buy groceries\n2. [x] Walk dog');
  });

  it('right-aligns ids of different widths', () => {
    const output = formatTodos([todo(9, 'nine'), todo(10, 'ten', true)]);
