'use strict';

// End-to-end tests: run index.js as a child process inside a fresh temp
// directory, exactly as a user would.

const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const CLI = path.join(__dirname, '..', 'index.js');

let dir;
let file;

function run(...args) {
  const result = spawnSync(process.execPath, [CLI, ...args], { cwd: dir, encoding: 'utf8' });
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

function readTodos() {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function writeTodos(todos) {
  fs.writeFileSync(file, JSON.stringify(todos));
}

// Asserts the command failed with the given message and printed nothing to stdout.
function assertFails(result, messagePattern) {
  assert.equal(result.code, 1);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, messagePattern);
}

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
  file = path.join(dir, 'todos.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

describe('general usage', () => {
  it('prints usage to stderr and exits 1 when no command is given', () => {
    const result = run();
    assertFails(result, /Usage: node index\.js <command>/);
    assert.match(result.stderr, /add <text>/);
    assert.match(result.stderr, /list/);
    assert.match(result.stderr, /complete <id>/);
    assert.match(result.stderr, /delete <id>/);
  });

  for (const flag of ['help', '--help', '-h']) {
    it(`prints usage to stdout and exits 0 for "${flag}"`, () => {
      const result = run(flag);
      assert.equal(result.code, 0);
      assert.match(result.stdout, /Usage: node index\.js <command>/);
      assert.equal(result.stderr, '');
    });
  }

  it('rejects unknown commands', () => {
    const result = run('frobnicate');
    assertFails(result, /Unknown command "frobnicate"/);
    assert.match(result.stderr, /Usage:/);
  });

  it('treats commands as case-sensitive', () => {
    assertFails(run('ADD', 'x'), /Unknown command "ADD"/);
  });

  it('does not create todos.json for commands that do not modify data', () => {
    run();
    run('help');
    run('list');
    run('bogus');
    assert.equal(fs.existsSync(file), false);
  });
});

describe('add', () => {
  it('adds a todo and stores it in todos.json in the current directory', () => {
    const before = Date.now();
    const result = run('add', 'Buy groceries');
    const after = Date.now();

    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Added todo #1: Buy groceries\n');
    assert.equal(result.stderr, '');

    const todos = readTodos();
    assert.equal(todos.length, 1);
    const [todo] = todos;
    assert.deepEqual(Object.keys(todo).sort(), ['completed', 'createdAt', 'id', 'text']);
    assert.equal(todo.id, 1);
    assert.equal(todo.text, 'Buy groceries');
    assert.equal(todo.completed, false);
    assert.equal(new Date(todo.createdAt).toISOString(), todo.createdAt);
    const created = Date.parse(todo.createdAt);
    assert.ok(created >= before && created <= after, 'createdAt should be the current time');
  });

  it('auto-increments ids across invocations', () => {
    assert.equal(run('add', 'first').stdout, 'Added todo #1: first\n');
    assert.equal(run('add', 'second').stdout, 'Added todo #2: second\n');
    assert.equal(run('add', 'third').stdout, 'Added todo #3: third\n');
    assert.deepEqual(readTodos().map((t) => [t.id, t.text]), [
      [1, 'first'],
      [2, 'second'],
      [3, 'third'],
    ]);
  });

  it('keeps incrementing after a todo in the middle is deleted', () => {
    run('add', 'a');
    run('add', 'b');
    run('add', 'c');
    run('delete', '2');
    assert.equal(run('add', 'd').stdout, 'Added todo #4: d\n');
    assert.deepEqual(readTodos().map((t) => t.id), [1, 3, 4]);
  });

  it('joins unquoted words into a single todo', () => {
    const result = run('add', 'Buy', 'some', 'groceries');
    assert.equal(result.code, 0);
    assert.equal(readTodos()[0].text, 'Buy some groceries');
  });

  it('trims surrounding whitespace from the text', () => {
    run('add', '   Walk the dog   ');
    assert.equal(readTodos()[0].text, 'Walk the dog');
  });

  it('preserves special characters and unicode', () => {
    const text = 'Café ☕ — "quotes", \'apostrophes\' & <tags> 日本語';
    assert.equal(run('add', text).code, 0);
    assert.equal(readTodos()[0].text, text);
    assert.equal(run('list').stdout, `1. [ ] ${text}\n`);
  });

  it('allows text that looks like a flag or a command name', () => {
    run('add', '--help');
    run('add', 'delete');
    assert.deepEqual(readTodos().map((t) => t.text), ['--help', 'delete']);
  });

  it('allows duplicate todo text', () => {
    run('add', 'same');
    run('add', 'same');
    assert.deepEqual(readTodos().map((t) => t.id), [1, 2]);
  });

  it('fails when the text is missing', () => {
    assertFails(run('add'), /Missing todo text/);
    assert.equal(fs.existsSync(file), false);
  });

  it('fails when the text is empty or whitespace-only', () => {
    assertFails(run('add', ''), /cannot be empty/);
    assertFails(run('add', '   '), /cannot be empty/);
    assert.equal(fs.existsSync(file), false);
  });

  it('adds to an existing but empty todos.json', () => {
    fs.writeFileSync(file, '');
    assert.equal(run('add', 'x').code, 0);
    assert.equal(readTodos().length, 1);
  });
});

describe('list', () => {
  it('shows a friendly message when there is no todos.json', () => {
    const result = run('list');
    assert.equal(result.code, 0);
    assert.match(result.stdout, /No todos yet/);
    assert.equal(result.stderr, '');
  });

  it('shows a friendly message when todos.json holds an empty list', () => {
    writeTodos([]);
    const result = run('list');
    assert.equal(result.code, 0);
    assert.match(result.stdout, /No todos yet/);
  });

  it('shows a friendly message once every todo has been deleted', () => {
    run('add', 'a');
    run('delete', '1');
    assert.match(run('list').stdout, /No todos yet/);
  });

  it('shows the id, status indicator and text of every todo', () => {
    run('add', 'Buy groceries');
    run('add', 'Walk the dog');
    run('add', 'Write report');
    run('complete', '2');

    const result = run('list');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, '1. [ ] Buy groceries\n2. [x] Walk the dog\n3. [ ] Write report\n');
    assert.equal(result.stderr, '');
  });

  it('aligns ids of different widths', () => {
    for (let i = 1; i <= 10; i++) run('add', `task ${i}`);
    const lines = run('list').stdout.trimEnd().split('\n');
    assert.equal(lines.length, 10);
    assert.equal(lines[0], ' 1. [ ] task 1');
    assert.equal(lines[9], '10. [ ] task 10');
  });

  it('does not modify todos.json', () => {
    run('add', 'a');
    const before = fs.readFileSync(file, 'utf8');
    run('list');
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('rejects extra arguments', () => {
    assertFails(run('list', 'extra'), /Too many arguments/);
  });
});

describe('complete', () => {
